// Generated by tour2playwright from a Tour Recorder export, then hand-edited.
// Source tour: Finance: Print a Cheque for a Vendor Payment ( Bill - Cheque Payment - Print ) - Full Flow
// Hand edits: label/id-based selectors, state assertions, result screenshots, wide viewport, login fallback.
// WRITES (test database only): creates + posts one vendor bill (tagged [TEST]), pays it by cheque and prints the
// cheque. The bank journal's cheque settings are only RE-ENTERED with their current values, never changed.
import { test, expect } from "../../../../core/fixtures/index";
import { uniqueName } from "../../../../core/utils/RandomDataGenerator";
import type { Page, Locator } from "@playwright/test";
import fs from "node:fs";

const SHOT_DIR = "tools/tour2playwright/generated/screenshots/finance-print-a-cheque-for-a-vendor-payment-bill-cheque-payment-print-full-flow";
const JOURNAL = "Vendor Payment - Commercial";
const VENDOR = "MARS ELECTRIC";
const LINE = uniqueName("Electrical spare parts - training bill");

// A step's own screenshot is taken BEFORE its action; this keeps one of the finished screen.
async function resultShot(page: Page, n: number) {
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/step-${String(n).padStart(2, "0")}-result.png` });
}

// Screenshot the current page with the target element outlined.
async function shot(page: Page, loc: Locator, file: string) {
  try {
    await loc.scrollIntoViewIfNeeded({ timeout: 5000 });
    await loc.evaluate((el) => el.setAttribute("data-t2p", "1"));
    await page.addStyleTag({
      content: '[data-t2p="1"]{outline:3px solid #e01e5a !important;outline-offset:2px !important;}',
    });
  } catch {}
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/${file}` });
  try { await loc.evaluate((el) => el.removeAttribute("data-t2p")); } catch {}
}

// dd/mm/yyyy, the date format of this database
function today(): string {
  const d = new Date();
  const p = (n: number) => String(n).padStart(2, "0");
  return `${p(d.getDate())}/${p(d.getMonth() + 1)}/${d.getFullYear()}`;
}

test.describe("Finance: Print a Cheque for a Vendor Payment ( Bill - Cheque Payment - Print ) - Full Flow @module:accounting @step:business @e2e", () => {
  // At the default 1280px some top-menu entries collapse into the "+" overflow.
  test.use({ viewport: { width: 1600, height: 900 } });

  test("Finance: Print a Cheque for a Vendor Payment ( Bill - Cheque Payment - Print ) - Full Flow", async ({ page }) => {
    test.setTimeout(300_000);
    await page.goto("/web");

    // The saved browser session can expire — fall back to the login form if we got bounced to it.
    const emailBox = page.getByRole("textbox", { name: "Email" });
    if (await emailBox.isVisible({ timeout: 8_000 }).catch(() => false)) {
      await emailBox.fill(process.env.ADMIN_EMAIL ?? "admin");
      await page.getByRole("textbox", { name: "Password" }).fill(process.env.ADMIN_PASSWORD ?? "admin");
      await page.getByRole("button", { name: "Log in" }).click();
      await page.waitForSelector(".o_main_navbar, .o_home_menu", { state: "visible", timeout: 45_000 });
    }
    await page.waitForLoadState("networkidle", { timeout: 10_000 }).catch(() => {});

    // Open the Accounting app first (the tour starts inside it).
    await page.locator('[data-menu-xmlid="account_accountant.menu_accounting"]').first().click();
    await expect(page.locator(".o_menu_sections")).toBeVisible({ timeout: 45000 });

    const run = async (n: number, title: string, loc: Locator, act?: (l: Locator) => Promise<void>, result = false) => {
      await test.step(`${String(n).padStart(2, "0")}. ${title}`, async () => {
        const l = loc.first();
        await l.waitFor({ state: "visible", timeout: 45000 });
        await shot(page, l, `step-${String(n).padStart(2, "0")}.png`);
        if (act) await act(l);
        if (result) await resultShot(page, n);
      });
    };
    const topMenu = (name: string) => page.locator(".o_menu_sections .dropdown-toggle, .o_menu_sections > a").filter({ hasText: new RegExp(`^${name}$`) });
    const dropItem = (name: string | RegExp) => page.locator(".dropdown-menu .dropdown-item").filter({ hasText: name });
    const modal = page.locator(".modal:visible").last();
    const pickOption = async (input: Locator, text: string) => {
      await input.fill(text);
      const opt = page.locator(".o-autocomplete--dropdown-item").filter({ hasText: new RegExp(text, "i") }).first();
      await opt.waitFor({ state: "visible", timeout: 15000 });
      await opt.click();
    };

    // ------------------------------------------------------------------ Part 1: the bank journal
    await test.step("01. Open hidden menus", async () => {
      // On a wide window every menu entry fits, so there may be no "+" to click.
      const more = page.locator(".o_menu_sections_more button").first();
      const target = (await more.isVisible({ timeout: 3000 }).catch(() => false)) ? more : page.locator(".o_menu_sections").first();
      await shot(page, target, "step-01.png");
    });
    await run(2, "Journals", topMenu("Configuration"), async (l) => {
      await l.click();
      const item = page.locator('[data-menu-xmlid="account.menu_action_account_journal_form"]').first();
      await item.waitFor({ state: "visible", timeout: 15000 });
      await resultShot(page, 2);
      await item.click();
      await expect(page.locator(".o_list_view"), "Journals list opened").toBeVisible({ timeout: 30000 });
    });
    await run(3, "Search the bank journal", page.locator("input.o_searchview_input"), async (l) => {
      await l.fill(JOURNAL);
      await l.press("Enter");
      await expect(page.locator(".o_data_row").filter({ hasText: JOURNAL }).first(), "journal found").toBeVisible({ timeout: 30000 });
    }, true);
    await run(4, JOURNAL, page.locator(".o_data_row").filter({ hasText: JOURNAL }).locator('td[name="name"]'), async (l) => {
      await l.click();
      await expect(page.locator(".o_form_view"), "journal form opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(5, "Outgoing Payments", page.locator('a[name="page_outgoing_payments"]'), async (l) => {
      await l.click();
      await expect(page.locator(".o_notebook .tab-pane.active").filter({ hasText: /Checks|Manual/ })).toBeVisible({ timeout: 15000 });
    }, true);
    await run(6, "Checks", page.locator(".tab-pane.active tr.o_data_row").filter({ hasText: /Checks/ }), async (l) => {
      await expect(l, "the Checks payment method is listed").toBeVisible();
    });
    // 7-9: Manual Numbering is kept as it is (ticked if it was off) and the next number is re-entered unchanged.
    await run(7, "Manual Numbering", page.locator("#check_manual_sequencing_0"), async (l) => {
      if (!(await l.isChecked())) await l.check();
      await expect(l, "manual numbering is on").toBeChecked();
    }, true);
    let nextNumber = "";
    await run(8, "Next Cheque Number", page.locator("#check_next_number_0"), async (l) => {
      nextNumber = (await l.inputValue()).trim();
      if (!nextNumber) { nextNumber = "1000"; await l.fill(nextNumber); }
      await expect(l).toHaveValue(nextNumber);
    }, true);
    await test.step("09. Save journal", async () => {
      const saveBtn = page.locator("button.o_form_button_save").first();
      if (await saveBtn.isVisible({ timeout: 2000 }).catch(() => false)) {
        await shot(page, saveBtn, "step-09.png");
        await saveBtn.click();
        await expect(saveBtn, "journal saved").toBeHidden({ timeout: 30000 });
      } else {
        // Nothing was changed, so Odoo shows no Save button — point at the form status area instead.
        await shot(page, page.locator(".o_form_status_indicator, .o_control_panel").first(), "step-09.png");
      }
      await resultShot(page, 9);
    });

    // ------------------------------------------------------------------ Part 2: the vendor bill
    await run(10, "Vendors menu", topMenu("Vendors"), async (l) => {
      await l.click();
      await expect(dropItem(/^Bills$/).first()).toBeVisible();
    }, true);
    await run(11, "Bills", dropItem(/^Bills$/), async (l) => {
      await l.click();
      await expect(page.locator(".o_list_view"), "bills list opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(12, "New", page.getByRole("button", { name: "New", exact: true }), async (l) => {
      await l.click();
      await expect(page.locator(".o_form_view"), "new bill form opened").toBeVisible({ timeout: 30000 });
    }, true);
    // A new bill can open on another journal (here "Advanced Cash Purchase"), which has no Vendor field.
    // Switching to the Vendor Bills journal (the tour's step 15) is then needed BEFORE the vendor can be chosen.
    const journalInput = () => page.locator(".o_field_widget[name='journal_id'] input").first();
    if (!(await page.locator(".o_field_widget[name=partner_id] input").isVisible({ timeout: 3000 }).catch(() => false))) {
      await journalInput().click();
      await pickOption(journalInput(), "Vendor Bills");
      await expect(page.locator(".o_field_widget[name=partner_id] input"), "vendor field appears for the Vendor Bills journal").toBeVisible({ timeout: 30000 });
    }
    await run(13, "Select the vendor", page.locator(".o_field_widget[name=partner_id] input"), async (l) => {
      await pickOption(l, VENDOR);
      await expect(l, "vendor chosen").toHaveValue(new RegExp(VENDOR, "i"));
    }, true);
    await run(14, "Bill Date", page.locator("#invoice_date_0"), async (l) => {
      await l.fill(today());
      await l.press("Tab");
      await expect(l).toHaveValue(today());
    }, true);
    await run(15, "Journal", journalInput(), async (l) => {
      // A new bill can open on another journal (here "Advanced Cash Purchase"): switch it to the normal purchase journal.
      await l.click();
      await l.fill("Vendor Bills");
      const exact = page.locator(".o-autocomplete--dropdown-item").filter({ hasText: /^\s*Vendor Bills\s*$/ }).first();
      const any = page.locator(".o-autocomplete--dropdown-item").filter({ hasText: /Vendor Bills/i }).first();
      await any.waitFor({ state: "visible", timeout: 15000 });
      await ((await exact.isVisible().catch(() => false)) ? exact : any).click();
      await expect(l, "journal is Vendor Bills").toHaveValue(/Vendor Bills/i);
      await expect(page.locator(".o_field_widget[name=partner_id] input"), "vendor is still set").toHaveValue(new RegExp(VENDOR, "i"));
    }, true);
    await run(16, "Add a line", page.locator("td.o_field_x2many_list_row_add a").first(), async (l) => {
      await l.click();
      await expect(page.locator("textarea.o_input, .o_selected_row").first(), "new line opened").toBeVisible({ timeout: 15000 });
    }, true);
    await run(17, "Line description", page.locator(".o_selected_row textarea, textarea.o_input").first(), async (l) => {
      await l.fill(LINE);
      await expect(l).toHaveValue(LINE);
    }, true);
    await run(18, "Unit price", page.locator('.o_selected_row td[name="price_unit"], td[name="price_unit"]').first(), async (l) => {
      await l.click();
      const input = page.locator('.o_selected_row td[name="price_unit"] input').first();
      await input.fill("25000");
      await input.press("Tab");
      await expect(page.locator(".o_field_widget[name='amount_total'], .oe_subtotal_footer").first(), "bill total updated").toContainText(/25,000/, { timeout: 15000 });
    }, true);
    await run(19, "Confirm", page.locator(".o_statusbar_buttons button").filter({ hasText: /^Confirm$/ }), async (l) => {
      await l.click();
      await expect(page.locator(".o_statusbar_status .o_arrow_button_current"), "bill is Posted").toContainText("Posted", { timeout: 30000 });
    }, true);

    // ------------------------------------------------------------------ Part 3: pay by cheque
    await run(20, "Register Payment", page.locator(".o_statusbar_buttons button").filter({ hasText: /Register Payment|^Pay$/ }), async (l) => {
      await l.click();
      await expect(page.locator(".modal:visible"), "payment wizard opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(21, "Payment journal", page.locator(".modal:visible #journal_id_0, .modal:visible [name='journal_id'] input").first(), async (l) => {
      await pickOption(l, JOURNAL);
      await expect(l, "payment journal chosen").toHaveValue(new RegExp(JOURNAL.replace(/ - /, ".*"), "i"));
    }, true);
    await run(22, "Payment Method - Checks", page.locator(".modal:visible #payment_method_line_id_0, .modal:visible [name='payment_method_line_id'] select").first(), async (l) => {
      await pickOption(l, "Checks");
      await expect(l, "payment method is Checks").toHaveValue(/Checks/i);
    }, true);
    await run(23, "Create Payment", page.locator(".modal:visible footer button, .modal-footer:visible button").filter({ hasText: /^Create Payment$/ }), async (l) => {
      await l.click();
      await expect(page.locator(".modal:visible"), "wizard closed").toBeHidden({ timeout: 45000 });
      await expect(page.locator(".o_form_view"), "bill is Paid").toContainText(/Paid|In Payment/, { timeout: 30000 });
    }, true);

    // ------------------------------------------------------------------ Part 4: print the cheque
    await run(24, "Vendors menu (payments)", topMenu("Vendors"), async (l) => {
      await l.click();
      await expect(dropItem(/^Payments$/).first()).toBeVisible();
    }, true);
    await run(25, "Payments", dropItem(/^Payments$/), async (l) => {
      await l.click();
      await expect(page.locator(".o_list_view"), "payments list opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(26, "Open the cheque payment", page.locator(".o_data_row").filter({ hasText: /Checks/ }), async (l) => {
      await l.click();
      await expect(page.locator(".o_form_view"), "payment opened").toBeVisible({ timeout: 30000 });
    }, true);
    let checkNumber = "";
    await run(27, "Check Number assigned", page.locator('div[name="check_number"]'), async (l) => {
      checkNumber = (await l.innerText()).trim();
      expect(checkNumber, "a check number is stamped on the payment").toMatch(/\d/);
    });
    await run(28, "Cheque Number to print", page.locator("#cheque_number_0"), async (l) => {
      await l.fill(checkNumber.replace(/\D/g, "") || "1");
      await l.press("Tab");
      await expect(l).toHaveValue(/\d/);
    }, true);
    await run(29, "Print Cheque", page.locator("button").filter({ hasText: /^Print Cheque$/ }), async (l) => {
      await l.click();
      await expect(page.locator(".modal:visible"), "cheque wizard opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(30, "Cheque Format", page.locator(".modal:visible #cheque_format_id_0"), async (l) => {
      if (!(await l.inputValue()).trim()) {
        await l.click();
        const first = page.locator(".o-autocomplete--dropdown-item").first();
        await first.waitFor({ state: "visible", timeout: 15000 });
        await first.click();
      }
      await expect(l, "a cheque format is selected").toHaveValue(/.+/);
    }, true);
    await run(31, "Print", page.locator('.modal:visible button[name="action_call_report"]'), async (l) => {
      // Printing makes Odoo build the cheque PDF: it arrives as a download or a new tab, or the dialog just closes.
      const outcome = Promise.race([
        page.waitForEvent("download", { timeout: 60000 }).then(() => "download"),
        page.context().waitForEvent("page", { timeout: 60000 }).then(() => "tab"),
        page.locator(".modal:visible").waitFor({ state: "hidden", timeout: 60000 }).then(() => "closed"),
      ]);
      await l.click();
      expect(["download", "tab", "closed"]).toContain(await outcome);
    });
  });
});
